package cn.yueji.balance;

import java.time.*;
import java.util.*;
import org.json.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class V4712RulesTest {
    LocalDateTime at(String time){return LocalDateTime.parse(time);}
    Ledger.Data data(long opening){Ledger.Data d=new Ledger.Data();d.settings.autoRefresh=false;Ledger.Account a=new Ledger.Account(1,"账户A","银行");a.created=at("2026-09-30T20:00");a.opening=opening;d.accounts.add(a);MonthLedger.updateAccount(d,1,a.created,opening);return d;}
    Ledger.Entry entry(Ledger.Data d,String kind,long amount,String time){Ledger.Entry e=new Ledger.Entry(d.nextId(),kind.equals(Ledger.INCOME),amount,at(time),"测试记录","",1);e.kind=kind;e.category="其他";e.cashLinked=true;e.nearestCash=!kind.equals(Ledger.REIMBURSE);d.entries.add(e);return e;}
    long expense(Ledger.Data d){return Ledger.month(d,YearMonth.of(2026,10)).expense;}
    @Test public void requestedIncomeLargeExpenseExampleIsFiveHundredNotSevenHundred(){Ledger.Data d=data(200000);entry(d,Ledger.INCOME,100000,"2026-10-10T12:00");LedgerStore.validate(d);assertEquals(300000,d.balance(d.accounts.get(0)));entry(d,Ledger.LARGE,20000,"2026-10-20T12:00");LedgerStore.validate(d);assertEquals(280000,d.balance(d.accounts.get(0)));assertFalse(Ledger.month(d,YearMonth.of(2026,10)).hasData());MonthLedger.updateAccount(d,1,at("2026-10-31T20:00"),250000);LedgerStore.validate(d);assertEquals(250000,d.balance(d.accounts.get(0)));assertEquals(50000,expense(d));assertEquals(2,d.snapshots.size());assertEquals(2,AccountCash.flows(d).size());}
    @Test public void requestedFundExampleResetsAtRealObservation(){Ledger.Data d=data(600000);MonthLedger.updateAccount(d,1,at("2026-10-11T12:00"),600000);FundTransactions.save(d,0,0,"006431",200000,30,at("2026-10-15T12:00"),null,"离线",false,true,1,new TradingCalendar());LedgerStore.validate(d);assertEquals(400000,d.balance(d.accounts.get(0)));assertEquals(0,expense(d));MonthLedger.updateAccount(d,1,at("2026-10-20T12:00"),300000);LedgerStore.validate(d);assertEquals(300000,d.balance(d.accounts.get(0)));assertEquals(100000,expense(d));assertEquals(-200000,AccountCash.flows(d).get(0).delta);assertEquals(3,d.snapshots.size());}
    @Test public void crossMonthReimbursementIsExcludedAndNeverIncome(){Ledger.Data d=data(500000);Ledger.Entry e=entry(d,Ledger.REIMBURSE,80000,"2026-10-10T12:00");MonthLedger.updateAccount(d,1,at("2026-10-31T20:00"),400000);Ledger.Receipt r=new Ledger.Receipt(80000,at("2026-11-01T09:00"));r.accountId=1;r.cashLinked=true;e.receipts.add(r);e.status=e.reimbursementStatus();LedgerStore.validate(d);assertEquals(20000,expense(d));assertEquals(480000,d.balance(d.accounts.get(0)));assertEquals(0,Ledger.income(d,2026));assertEquals(2,AccountCash.flows(d).size());assertEquals(0,Ledger.month(d,YearMonth.of(2026,11)).expense);MonthLedger.updateAccount(d,1,at("2026-11-01T10:00"),470000);LedgerStore.validate(d);assertEquals(10000,Ledger.month(d,YearMonth.of(2026,11)).expense);assertEquals(0,Ledger.income(d,2026));}
    @Test public void reimbursementReceiptAtMidnightStaysOutOfBothPersonalMonths(){Ledger.Data d=data(500000);Ledger.Entry e=entry(d,Ledger.REIMBURSE,80000,"2026-10-10T12:00");MonthLedger.updateAccount(d,1,at("2026-10-31T20:00"),400000);Ledger.Receipt r=new Ledger.Receipt(80000,at("2026-11-01T00:00"));r.accountId=1;r.cashLinked=true;e.receipts.add(r);e.status=e.reimbursementStatus();MonthLedger.updateAccount(d,1,r.at,480000);MonthLedger.updateAccount(d,1,at("2026-11-01T10:00"),470000);LedgerStore.validate(d);assertEquals(20000,expense(d));assertEquals(10000,Ledger.month(d,YearMonth.of(2026,11)).expense);assertEquals(0,Ledger.income(d,2026));}
    @Test public void sameTimeIndependentIncomeAndReceiptKeepAllSourceIdentities(){Ledger.Data d=data(500000);Ledger.Entry a=entry(d,Ledger.INCOME,10000,"2026-10-10T12:00"),b=entry(d,Ledger.INCOME,20000,"2026-10-10T12:00"),e=entry(d,Ledger.REIMBURSE,30000,"2026-10-09T12:00");for(int i=0;i<2;i++){Ledger.Receipt r=new Ledger.Receipt(15000,a.at);r.accountId=1;r.cashLinked=true;e.receipts.add(r);}e.status=e.reimbursementStatus();LedgerStore.validate(d);assertEquals(5,AccountCash.rows(d,d.accounts.get(0)).size());assertEquals(530000,d.balance(d.accounts.get(0)));assertNotEquals(e.receipts.get(0).id,e.receipts.get(1).id);Set<String> keys=new HashSet<>();for(AccountCash.Flow f:AccountCash.flows(d))assertTrue(keys.add(f.key));assertNotEquals(a.id,b.id);}
    @Test public void hiddenRowRetainsMoneyAndSourceResaveRestoresExactlyOnce(){Ledger.Data d=data(200000);Ledger.Entry e=entry(d,Ledger.INCOME,50000,"2026-10-10T12:00");LedgerStore.validate(d);AccountCash.hide(d,1,"entry:"+e.id);LedgerStore.validate(d);assertEquals(0,AccountCash.rows(d,d.accounts.get(0)).size());assertEquals(250000,d.balance(d.accounts.get(0)));d=LedgerStore.decode(LedgerStore.encode(d));LedgerStore.validate(d);e=d.entries.get(0);AccountCash.restoreEntry(d,e);AccountCash.restoreEntry(d,e);LedgerStore.validate(d);assertEquals(1,AccountCash.rows(d,d.accounts.get(0)).size());assertEquals(250000,d.balance(d.accounts.get(0)));assertEquals(1,d.entries.size());}
    @Test public void hidingOneSameTimeIncomeNeverHidesItsNeighbour(){Ledger.Data d=data(200000);Ledger.Entry a=entry(d,Ledger.INCOME,10000,"2026-10-10T12:00"),b=entry(d,Ledger.INCOME,20000,"2026-10-10T12:00");AccountCash.hide(d,1,"entry:"+a.id);LedgerStore.validate(d);assertEquals(1,AccountCash.rows(d,d.accounts.get(0)).size());assertEquals("entry:"+b.id,AccountCash.rows(d,d.accounts.get(0)).get(0).key);assertEquals(230000,d.balance(d.accounts.get(0)));}
    @Test public void legacyGeneratedSnapshotsAreRemovedWithoutLosingRealCellsOrSources(){Ledger.Data d=data(200000);Ledger.Entry e=entry(d,Ledger.INCOME,50000,"2026-10-10T12:00");Ledger.Snapshot generated=new Ledger.Snapshot(d.nextId(),e.at,"旧推算");generated.cashGenerated=true;generated.balances.put(1L,250000L);d.snapshots.add(generated);Ledger.Account other=new Ledger.Account(2,"账户B","现金");other.created=d.accounts.get(0).created;d.accounts.add(other);Ledger.Snapshot mixed=new Ledger.Snapshot(d.nextId(),at("2026-10-11T12:00"),"");mixed.partial=true;mixed.cashAccounts.add(1L);mixed.balances.put(1L,250000L);mixed.balances.put(2L,900L);mixed.notes.put(2L,"实测不能丢");d.snapshots.add(mixed);Ledger.Data restored=LedgerStore.decode(LedgerStore.encode(d));LedgerStore.validate(restored);assertEquals(2,restored.snapshots.size());assertEquals(250000,restored.balance(restored.accounts.get(0)));assertFalse(restored.latest().balances.containsKey(1L));assertEquals("实测不能丢",restored.latest().notes.get(2L));assertEquals(1,AccountCash.flows(restored).size());}
    @Test public void legacyTimestampSuppressionCannotHideNewAmountRows(){Ledger.Data d=data(200000);Ledger.Entry e=entry(d,Ledger.INCOME,50000,"2026-10-10T12:00");d.accounts.get(0).skippedCashObservations.add(e.at);LedgerStore.validate(d);assertEquals(1,AccountCash.rows(d,d.accounts.get(0)).size());assertEquals(250000,d.balance(d.accounts.get(0)));}
    @Test public void fixedWholeMonthDoesNotBridgeOrChangeAfterIncomeBackfill(){Ledger.Data d=data(0);Ledger.HistoryMonth h=new Ledger.HistoryMonth(YearMonth.of(2026,9),12345,at("2026-10-01T00:00"));h.fixedCutoff=true;d.history.add(h);entry(d,Ledger.INCOME,100000,"2026-09-30T21:00");MonthLedger.updateAccount(d,1,at("2026-09-30T23:59"),100000);LedgerStore.validate(d);assertEquals(h.cutoff,Ledger.historyCutoff(d,h));assertEquals(12345,Ledger.month(d,h.month).expense);Ledger.Data restored=LedgerStore.decode(LedgerStore.encode(d));assertTrue(restored.history.get(0).fixedCutoff);assertEquals(12345,Ledger.month(restored,h.month).expense);}
    @Test public void dayPointCombinesBothAccountsAndLaterSameDayFlow(){Ledger.Data d=data(200000);Ledger.Account b=new Ledger.Account(2,"账户B","现金");b.created=d.accounts.get(0).created;b.opening=100000;d.accounts.add(b);MonthLedger.updateAccount(d,2,b.created,b.opening);MonthLedger.updateAccount(d,1,at("2026-10-10T10:00"),180000);MonthLedger.updateAccount(d,2,at("2026-10-10T18:00"),90000);entry(d,Ledger.INCOME,5000,"2026-10-10T20:00");LedgerStore.validate(d);List<AssetHistory.Point> points=AssetHistory.observations(d,at("2026-10-11T10:00"));assertEquals(2,points.size());assertEquals(at("2026-10-10T00:00"),points.get(1).at);assertEquals(Long.valueOf(275000),points.get(1).amount);assertEquals(2,AssetHistory.series(points,0).size());assertEquals(Long.valueOf(280000),AssetHistory.observations(d,at("2026-10-10T12:00")).get(1).amount);}
    @Test public void sameInstantRealBalanceAndIncomeStaySeparateWithoutDoubleCredit(){Ledger.Data d=data(200000);entry(d,Ledger.INCOME,50000,"2026-10-10T12:00");MonthLedger.updateAccount(d,1,at("2026-10-10T12:00"),240000);LedgerStore.validate(d);assertEquals(240000,d.balance(d.accounts.get(0)));assertEquals(10000,expense(d));assertEquals(2,AccountRecords.rows(d,d.accounts.get(0)).size());assertEquals(1,AccountCash.rows(d,d.accounts.get(0)).size());}
    @Test public void reSavingReceiptAndSourceChangeCannotDuplicateItsCredit(){Ledger.Data d=data(200000);Ledger.Entry e=entry(d,Ledger.REIMBURSE,50000,"2026-10-09T12:00");Ledger.Receipt r=new Ledger.Receipt(50000,at("2026-10-10T12:00"));r.accountId=1;r.cashLinked=true;e.receipts.add(r);e.status=e.reimbursementStatus();LedgerStore.validate(d);AccountCash.hide(d,1,"receipt:"+r.id);assertEquals(1,AccountCash.rows(d,d.accounts.get(0)).size());AccountCash.restoreEntry(d,e);LedgerStore.validate(d);assertEquals(2,AccountCash.rows(d,d.accounts.get(0)).size());assertEquals(200000,d.balance(d.accounts.get(0)));}
    @Test public void legacyFlagDoesNotTriggerNearestBalanceGeneration(){Ledger.Data d=data(500000);Ledger.Entry e=entry(d,Ledger.LARGE,100000,"2026-10-10T12:00");e.nearestCash=true;MonthLedger.updateAccount(d,1,at("2026-10-11T12:00"),300000);LedgerStore.validate(d);assertEquals(2,d.snapshots.size());assertEquals(300000,d.balance(d.accounts.get(0)));assertEquals(200000,expense(d));}
    @Test public void crossProductLegacyBuyIdsDoNotShareVisibilityKeys(){Ledger.Data d=data(600000);for(int i=0;i<2;i++){Ledger.Fund f=new Ledger.Fund();f.id=100+i;f.code=i==0?"006431":"006432";f.name="合成基金"+i;Ledger.FundBuy b=new Ledger.FundBuy();b.id=200;b.amount=10000;b.at=at("2026-10-10T12:00");b.buyAccountId=1;b.buyAccountLinked=true;f.buys.add(b);d.funds.add(f);}LedgerStore.validate(d);List<AccountCash.Flow> flows=AccountCash.flows(d);assertNotEquals(flows.get(0).key,flows.get(1).key);AccountCash.hide(d,1,flows.get(0).key);Ledger.Data restored=LedgerStore.decode(LedgerStore.encode(d));LedgerStore.validate(restored);assertEquals(1,AccountCash.rows(restored,restored.accounts.get(0)).size());assertEquals(580000,restored.balance(restored.accounts.get(0)));}
    @Test(expected=IllegalArgumentException.class) public void duplicateGenuineBalanceTimeStillRejected(){Ledger.Data d=data(200000);Ledger.Snapshot s=new Ledger.Snapshot(d.nextId(),d.snapshots.get(0).at,"");s.balances.put(1L,12345L);d.snapshots.add(s);LedgerStore.validate(d);}
    @Test(expected=IllegalArgumentException.class) public void malformedVisibilityListRejected()throws Exception{JSONObject root=new JSONObject(LedgerStore.encode(data(200000)));root.getJSONArray("accounts").getJSONObject(0).put("hiddenActivityKeys",new JSONArray().put(12));LedgerStore.decode(root.toString());}
    @Test(expected=IllegalArgumentException.class) public void duplicateReceiptIdentityRejected(){Ledger.Data d=data(200000);Ledger.Entry e=entry(d,Ledger.REIMBURSE,50000,"2026-10-09T12:00");for(int i=0;i<2;i++){Ledger.Receipt r=new Ledger.Receipt(25000,at("2026-10-10T12:00"));r.id=123;e.receipts.add(r);}e.status=e.reimbursementStatus();LedgerStore.validate(d);}
    @Test(expected=IllegalArgumentException.class) public void malformedFixedCutoffRejected()throws Exception{Ledger.Data d=data(200000);d.history.add(new Ledger.HistoryMonth(YearMonth.of(2026,9),1000,at("2026-10-01T00:00")));JSONObject root=new JSONObject(LedgerStore.encode(d));root.getJSONArray("history").getJSONObject(0).put("fixedCutoff","true");LedgerStore.decode(root.toString());}
}
